create table if not exists public.manila_site_texts(key text primary key,value text not null,updated_at timestamptz not null default now());alter table public.manila_site_texts enable row level security;drop policy if exists "read site texts" on public.manila_site_texts;create policy "read site texts" on public.manila_site_texts for select to anon,authenticated using(true);drop policy if exists "admin insert site texts" on public.manila_site_texts;create policy "admin insert site texts" on public.manila_site_texts for insert to authenticated with check(public.manila_is_admin());drop policy if exists "admin update site texts" on public.manila_site_texts;create policy "admin update site texts" on public.manila_site_texts for update to authenticated using(public.manila_is_admin()) with check(public.manila_is_admin());